    function testRegression_property() public {
        // Initial CEO is already set to 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26
        // prank as that address (the CEO) to call DrugDealer
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.prank(ceo);
        // First call: reference succeeds, second version also succeeds (require(msg.sender != ceoAddress) passes because ceoAddress == ceo)
