        address user1 = address(0x123);
        address user2 = address(0x456);

        // give user1 some ETH to buy drugs
        vm.deal(user1, 1 ether);
        vm.prank(user1);
        c.buyDrugs{value: 0.1 ether}();

        // record user2's claimedDrugs before collectDrugs
        uint256 before = c.claimedDrugs(user2);

        // user1 calls collectDrugs with user2 as referral
        vm.prank(user1);
        c.collectDrugs(user2);

