        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0.5 ether}(1000);

        // Get free kilos to have a drug-producing asset
        c.getFreeKilo();

        // Warp forward to accrue some drugs (e.g. 100 seconds, which is less than DRUGS_TO_PRODUCE_1KILO = 86400)
        vm.warp(block.timestamp + 100);

        // Collect drugs to claim some claimedDrugs (also adds referral bonus and marketDrugs)
        c.collectDrugs(address(0)); // no referral

        // Now sell drugs; this will transfer Ether to ceoAddress and msg.sender
        // Record balances before sell
        address ceo = c.ceoAddress();
        uint256 ceoBefore = ceo.balance;
        uint256 senderBefore = address(this).balance;

        // Execute sell
        c.sellDrugs();

        // Compute expected fee: 4% of drugValue; the reference pays fee to ceo and remainder to sender,
        // the bug pays full drugValue to ceo (so ceo receives more, sender receives less)
        uint256 ceoAfter = ceo.balance;
        uint256 senderAfter = address(this).balance;

        // In the reference version, ceo gets exactly 4% of drugValue (fee) and sender gets 96%.
        // In the bug version, ceo gets 100% of drugValue, and sender gets 0%.
        // We assert that sender's balance increased, which is true for reference but false for bug.
        assertTrue(senderAfter > senderBefore);
    }
}

